-- PT112-S1-Q15. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT112-S1-Q15$batch10$ AND q.stimulus=$batch10$In one study, engineering students who prepared for an exam by using toothpicks and string did no worse than similar students who prepared by using an expensive computer with sophisticated graphics. In another study, military personnel who trained on a costly high-tech simulator performed no better on a practical exam than did similar personnel who trained using an inexpensive cardboard model. So one should not always purchase technologically advanced educational tools.$batch10$ AND q.prompt=$batch10$Which one of the following principles, if valid, most helps to justify the reasoning above?$batch10$ AND q.correct_choice=$batch10$D$batch10$) THEN RAISE EXCEPTION 'Question changed: PT112-S1-Q15'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT112-S1-Q15$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S1-Q15'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT112-S1-Q15$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$One should not always buy technologically advanced educational tools.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$In two studies, students using cheap tools (toothpicks and string, a cardboard model) did just as well as students using expensive high-tech tools.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The studies show cheap tools can be as effective as expensive ones. The principle has to say that when a cheaper tool works just as well, you shouldn't pay for the expensive one.$batch10$), (3, $batch10$Goal$batch10$, $batch10$Don't buy expensive tools when cheaper tools are at least as effective.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT112-S1-Q15$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$The two studies aren't meant to contrast civilians with soldiers. They show the same lesson in both settings: cheap tools did as well.$batch10$), ($batch10$B$batch10$, $batch10$Nothing in the studies turns on whether the personnel were knowledgeable. The comparison is cheap tool against expensive tool.$batch10$), ($batch10$C$batch10$, $batch10$Whether spending is as justified for civilian as for military training doesn't matter. The argument says the expensive tool isn't always worth buying, in either setting.$batch10$), ($batch10$D$batch10$, $batch10$In both studies a cheaper tool was at least as effective. This principle says not to buy the expensive aid in that situation, so you shouldn't always buy high-tech tools.$batch10$), ($batch10$E$batch10$, $batch10$Learning styles and variety never come up. The studies compare cost and results, nothing else.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT112-S1-Q15$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
